struct posix_acl *convert_xfs_acl_to_posix(const struct xfs_acl *aclp) {
    int count = aclp->acl_count;
    struct posix_acl *posix_acl;
    int i;

    if (count < 0 || count > XFS_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    posix_acl = kzalloc(sizeof(struct posix_acl) + count * sizeof(struct posix_acl_entry), GFP_KERNEL);
    if (!posix_acl)
        return ERR_PTR(-ENOMEM);

    posix_acl->a_count = count;
    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *entry = &aclp->acl_entry[i];
        struct posix_acl_entry *posix_entry = &posix_acl->a_entries[i];

        switch (entry->e_tag) {
            case XFS_ACL_USER_OBJ:
                posix_entry->e_tag = POSIX_ACL_USER_OBJ;
                break;
            case XFS_ACL_GROUP_OBJ:
                posix_entry->e_tag = POSIX_ACL_GROUP_OBJ;
                break;
            case XFS_ACL_OTHER:
                posix_entry->e_tag = POSIX_ACL_OTHER;
                break;
            case XFS_ACL_USER:
                posix_entry->e_tag = POSIX_ACL_USER;
                posix_entry->e_uid = entry->e_id;
                break;
            case XFS_ACL_GROUP:
                posix_entry->e_tag = POSIX_ACL_GROUP;
                posix_entry->e_gid = entry->e_id;
                break;
            default:
                kfree(posix_acl);
                return ERR_PTR(-EINVAL);
        }

        posix_entry->e_perms = entry->e_perm;
    }

    return posix_acl;
}

struct posix_acl *xfs_acl_from_disk(struct xfs_acl *aclp) {
    int i;
    struct posix_acl *pacl;
    struct posix_acl_entry *ent;
    int count = be16_to_cpu(aclp->acl_count);

    if (count < 0 || count > XFS_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    pacl = posix_acl_alloc(count, GFP_KERNEL);
    if (!pacl)
        return ERR_PTR(-ENOMEM);

    ent = pacl->a_entries;
    for (i = 0; i < count; i++, ent++) {
        struct xfs_acl_entry *dacl = &aclp->acl_entry[i];
        __u32 tag = be32_to_cpu(dacl->e_tag);
        __u32 id = be32_to_cpu(dacl->e_id);
        __u16 perm = be16_to_cpu(dacl->e_perm);

        switch (tag) {
            case XFS_ACL_USER_OBJ:
                ent->e_tag = POSIX_ACL_USER_OBJ;
                ent->e_id = ACL_UNDEFINED_ID;
                break;
            case XFS_ACL_USER:
                ent->e_tag = POSIX_ACL_USER;
                ent->e_id = id;
                break;
            case XFS_ACL_GROUP_OBJ:
                ent->e_tag = POSIX_ACL_GROUP_OBJ;
                ent->e_id = ACL_UNDEFINED_ID;
                break;
            case XFS_ACL_GROUP:
                ent->e_tag = POSIX_ACL_GROUP;
                ent->e_id = id;
                break;
            case XFS_ACL_OTHER:
                ent->e_tag = POSIX_ACL_OTHER;
                ent->e_id = ACL_UNDEFINED_ID;
                break;
            default:
                posix_acl_release(pacl);
                return ERR_PTR(-EINVAL);
        }

        ent->e_perm = perm;
    }

    return pacl;
}

