struct posix_acl *convert_xfs_acl_to_posix(const struct xfs_acl *aclp) {
    int count = aclp->acl_count;
    struct posix_acl *acl;
    int i;

    if (count < 0 || count > XFS_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    acl = kmalloc(sizeof(struct posix_acl) + count * sizeof(struct posix_acl_entry), GFP_KERNEL);
    if (!acl)
        return ERR_PTR(-ENOMEM);

    acl->a_count = count;
    acl->a_entries = 0;

    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *e = &aclp->acl_entry[i];
        struct posix_acl_entry *pe = &acl->a_entries[i];

        pe->e_tag = e->ae_tag;
        pe->e_perm = e->ae_perm;

        switch (e->ae_tag) {
            case ACL_USER_OBJ:
            case ACL_GROUP_OBJ:
            case ACL_MASK:
            case ACL_OTHER:
                pe->e_id = ACL_UNDEFINED_ID;
                break;
            case ACL_USER:
            case ACL_GROUP:
                pe->e_id = e->ae_id;
                break;
            default:
                kfree(acl);
                return ERR_PTR(-EINVAL);
        }
    }

    return acl;
}

